import type { PersonId, SlotKey } from '../../grammar/types'
import type { LocalizedText } from '../../types/content'
import { t } from '../explanations/text'

export interface YkiDomain {
  id: string
  title: LocalizedText
  situation: string
  /** Sentence tags used for reading and fill-in practice. */
  tags: string[]
  words: string[]
  writing: {
    task: LocalizedText
    /** Curated model answer. */
    model: string
    /** Noun forms used in the model answer, generated by the engine. */
    checklist: { lexemeId: string; slot: SlotKey; person?: PersonId }[]
  }
  speaking: string[]
}

